CREATE TABLE reports (
id INTEGER NOT NULL,
recipe_id INTEGER NOT NULL,
reasons text NOT NULL,
other_reason text DEFAULT NULL,
reporter_email varchar(255) DEFAULT NULL,
reported_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
status TEXT CHECK (status IN ('pending','reviewed','resolved')) DEFAULT 'pending'
);

CREATE TABLE submission_requests (
id INTEGER NOT NULL,
title varchar(255) NOT NULL,
category varchar(100) DEFAULT NULL,
description text DEFAULT NULL,
image varchar(255) DEFAULT NULL,
location varchar(255) DEFAULT NULL,
organizerName varchar(255) DEFAULT NULL,
organizerEmail varchar(255) DEFAULT NULL,
organizerAddress varchar(255) DEFAULT NULL,
status varchar(50) DEFAULT NULL,
tags text DEFAULT NULL,
reference varchar(255) DEFAULT NULL,
tutorialVideo varchar(255) DEFAULT NULL,
comment text DEFAULT NULL,
source varchar(100) DEFAULT NULL,
submission_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
action_date TIMESTAMP DEFAULT NULL,
admin_name varchar(100) DEFAULT NULL
);

INSERT INTO submission_requests (id, title, category, description, image, location, organizerName, organizerEmail, organizerAddress, status, tags, reference, tutorialVideo, comment, source, submission_date, action_date, admin_name) VALUES
